//! 🥡️ Typed default placement denies missing copy and empty arrays remain genuine values.
use semio_framework_value_native_default::{NativeDefault,NativeDefaultValue,NativeDefaultCursor,NativeArrayDefaultCursor};
use semio_framework_value_testing_admission::{self as fixture,BankWallet,EffectBank,Wallet,RetainedCloneGrant,RetainedCloneProgress,OriginalSourceTurnIdentity};
use semio_framework_value_native_decoding::native_decoding::{NativeDecodeControl,OriginalEffectAuthority,OriginalEffectProducer};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use semio_framework_value_control_contract::{OriginalEffectReply,OriginalEffectReplyComplete,RetainedAllocationEffect,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,ValueError};
use semio_framework_value_native_decoding::native_decoding::OriginalReceivingPrimary;

fn turn(bank:&mut EffectBank,grant:RetainedCloneGrant,maximum:u64,invoke:impl for<'reply>FnOnce(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>)->(RetainedCloneStep,u128,(usize,usize)){
 let mut answer=None;let ((poll,actual),heap)=observe(||bank.run(grant,maximum,|effect|{
  let before=effect.performed_work();let reply=OriginalEffectReply::borrow(&mut answer).unwrap();drop(invoke(effect,reply).unwrap());
  RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<(),ValueError>(()),work:effect.performed_work()-before})
 }));
 let RetainedWorkPoll::Complete(outcome)=poll else{panic!("pure default publication unexpectedly pending")};outcome.result.unwrap();assert_eq!(actual,None);
 if outcome.work>0{assert_eq!(bank.take_admitted(),Some(true))}else{assert_eq!(bank.take_admitted(),None)}
 let step=*answer.as_ref().expect("original borrowed reply recorded").as_ref().expect("default publication");bank.post(step.progress(),grant,heap);clear(bank,&mut answer);(step,outcome.work,heap)
}
fn clear<T>(bank:&mut EffectBank,slot:&mut Option<T>){let bytes=std::mem::size_of::<Option<T>>();assert!(bytes<=4096);let grant=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(slot.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("default header clear pending")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),grant,heap)}
struct CloseArray<'a>(&'a mut NativeArrayDefaultCursor<u64,0>);
impl semio_framework_value_control_contract::OriginalEffectProducer for CloseArray<'_>{type Output=RetainedCloneStep;type Failure=semio_framework_value_native_decoding::OriginalRetirementFailure;type Context<'a,'b>=() where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity> where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError> where 'b:'a{self.0.close_step(4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError> where 'b:'a{self.0.recover_close_step(4096,effect,reply)}}
#[test]
fn empty_string_default_requires_its_real_option_placement_and_never_allocates(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️work/🥡️placement/🔣️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut output=None;let mut grant=bank.loan(1,4096);grant.maximum_copy_bytes=0;
 let(step,work,heap)=turn(&mut bank,grant,1,|effect,reply|<String as NativeDefaultValue>::admit_default(&mut output,effect,reply));assert_eq!(work,0);assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(output,None);assert_eq!(heap,(0,0));
 let demand=<String as NativeDefaultValue>::default_demand();assert_eq!(demand.copy_bytes,std::mem::size_of::<Option<String>>());assert!(demand.copy_bytes>0);let grant=bank.loan(1,demand.copy_bytes);
 let(_,work,heap)=turn(&mut bank,grant,<String as NativeDefaultValue>::default_work_demand().unwrap(),|effect,reply|<String as NativeDefaultValue>::admit_default(&mut output,effect,reply));assert_eq!(work,1);assert_eq!(heap,(0,0));assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),law["string"]);assert_eq!(output.as_ref().unwrap().capacity(),0);clear(&mut bank,&mut output);assert!(bank.into_wallet().is_ok());
}
type Op<'a>=&'a mut dyn for<'r> FnMut(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>;
struct Resident;
impl OriginalEffectProducer for Resident{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=Op<'turn> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{context(effect,reply)}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
fn synchronous(poll:RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous default action stayed pending")}}
fn through_reply(bank:&mut EffectBank,grant:RetainedCloneGrant,maximum:u64,operation:Op<'_>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
 let mut authority=OriginalEffectAuthority::new(Resident);let mut slot=None;let mut reply=None;let mut operation=operation;
 let(poll,_)=bank.run(grant,maximum,|effect|match authority.drive(&mut operation,effect,&mut slot){Ok(true)=>{slot.as_mut().expect("settled action").transfer_reply(&mut reply).expect("empty reply slot");RetainedWorkPoll::Complete(RetainedWorkOutcome{result:reply.take().expect("recorded reply"),work:effect.performed_work()})},Ok(false)=>RetainedWorkPoll::Pending{work:effect.performed_work()},Err(error)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error.into()),work:effect.performed_work()})});
 authority.finish(&mut slot).expect("reply transferred");drop(authority.into_producer().ok().expect("finished action"));assert_ne!(bank.take_admitted(),Some(false));synchronous(poll)
}
#[test]
fn empty_array_denies_zero_work_then_publishes_the_real_zero_length_value(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️work/🥡️placement/🔣️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let(mut cursor,heap)=observe(NativeArrayDefaultCursor::<u64,0>::new);assert_eq!(heap,(0,0));let grant=bank.loan(1,4096);
 let(step,work,heap)=turn(&mut bank,grant,0,|effect,reply|cursor.advance_local(4096,effect,reply));assert_eq!(work,0);assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(!cursor.output_ready());
 for _ in 0..10000{if cursor.output_ready(){break}let maximum=bank.wallet().remaining_work();let demand=cursor.demands(4096,maximum).unwrap();let selected=cursor.select_advance(4096,maximum).unwrap();let semio_framework_value_native_receiver_protocol::NativeAdvanceSelection::Local{work}=selected else{panic!("empty array selected a child")};let grant=bank.loan(1,demand.copy_bytes);turn(&mut bank,grant,work,|effect,reply|cursor.advance_local(4096,effect,reply));}
 assert!(cursor.output_ready());let mut output=None;let demand=cursor.take_demand().unwrap();let mut denied=bank.loan(1,demand.copy_bytes);denied.maximum_copy_bytes=0;let(step,work,_)=turn(&mut bank,denied,1,|effect,reply|cursor.take(&mut output,effect,reply));assert_eq!(work,0);assert_eq!(step.progress(),RetainedCloneProgress::default());assert!(output.is_none());
 let grant=bank.loan(1,demand.copy_bytes);turn(&mut bank,grant,cursor.take_work_demand().unwrap(),|effect,reply|cursor.take(&mut output,effect,reply));assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),law["emptyArray"]);clear(&mut bank,&mut output);
 let demand=cursor.begin_close_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let mut answer=None;let ((poll,actual),heap)=observe(||bank.run(grant,cursor.begin_close_work_demand().unwrap(),|effect|{let before=effect.performed_work();let reply=OriginalEffectReply::borrow(&mut answer).unwrap();let complete=cursor.begin_close_into(effect,reply).unwrap();assert!(complete.is_recorded());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(outcome)=poll else{panic!("pure close start unexpectedly pending")};outcome.result.unwrap();let progress=answer.as_ref().unwrap().as_ref().unwrap().progress();assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);clear(&mut bank,&mut answer);
 let mut authority=Some(semio_framework_value_control_contract::OriginalEffectAuthority::new(CloseArray(&mut cursor)));let mut action=None;let mut output=None;for _ in 0..32{let owner=&authority.as_ref().unwrap().producer().0;if owner.terminal_is_empty(){break}let demand=owner.close_demands(4096).unwrap();let work=owner.close_work_demand(4096).unwrap();let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{let before=effect.performed_work();let ready=authority.as_mut().unwrap().drive(&mut (),effect,&mut action).unwrap();if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()-before})}else{RetainedWorkPoll::Pending{work:effect.performed_work()-before}}}));let RetainedWorkPoll::Complete(outcome)=poll else{panic!("default close remains pending")};outcome.result.unwrap();let progress=action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,heap.0)}if outcome.work>0{assert_eq!(bank.take_admitted(),Some(true))}bank.post(progress,grant,heap);let demand=semio_framework_value_control_contract::OriginalEffectAuthority::<CloseArray<'_>>::transfer_reply_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(authority.as_mut().unwrap().transfer_reply_into(&(),&mut action,&mut output,effect))));let RetainedWorkPoll::Complete(outcome)=poll else{panic!("default reply transfer pending")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(outcome.result.unwrap().unwrap(),grant,heap);assert!(output.as_ref().unwrap().is_ok());clear(&mut bank,&mut output);}assert!(authority.as_ref().unwrap().producer().0.terminal_is_empty());let demand=semio_framework_value_control_contract::OriginalEffectAuthority::<CloseArray<'_>>::producer_transfer_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let mut returned=None;let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(semio_framework_value_control_contract::OriginalEffectAuthority::transfer_producer(&mut authority,&(),&mut returned,effect))));let RetainedWorkPoll::Complete(outcome)=poll else{panic!("default producer transfer pending")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(outcome.result.unwrap().unwrap(),grant,heap);clear(&mut bank,&mut returned);drop(returned);drop(authority);assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));let _wallet=bank.into_wallet().ok().expect("original finite wallet returned");
}
fn synchronous_close(poll:RetainedWorkPoll<RetainedCloneStep,semio_framework_value_testing_admission::OriginalRetirementFailure>)->RetainedWorkOutcome<RetainedCloneStep,semio_framework_value_testing_admission::OriginalRetirementFailure>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous default close stayed pending")}}
